@startuml

class CarPark {}

class Barrier {
  + raise()
}

class CardReader {
  + verifyCardNumber()
}

class Signal {}

class Sign {
  + displayFull()
  + switchOff()
}

class Card {
  + cardNumber : int
}

class StaffCard extends Card {
  + name : string
  + department : string
  + staffNumber : int
}

class GuestCard extends Card {
  + number : int
  + currentDate : date
}

class Employee {
  + name : string
  + department : string
  + staffNumber : int
}

class Driver {
  + name : string
}

CarPark "1" *-- "2" Barrier
CarPark "1" *-- "1" CardReader
CarPark "1" *-- "1" Sign
CardReader ..> Signal : triggers
Barrier ..> Signal : triggered by
Driver "1" -- "1" Card : wears
Driver "1" -- "1" Car {}
Car "1" -- "1" Barrier : passes through

@enduml

